#!/usr/bin/env node
'use strict';

const p = require('path');
const util = require('util');
const fs = require('fs');
const process = require('process');

const R = require('ramda');

const cli = require('./cli/index');
const Wry = require('./wry');
const WryError = require('./wryError');
const findPackageJson = require('./util/findPackageJson');

const readFileAsync = util.promisify(fs.readFile);

module.exports = async function (args) {
  try {
    const o = cli.options(args);

    if (o.help) {
      return cli.help();
    }

    if (o.version) {
      return cli.version();
    }

    // parse package.json
    const wryModule = new cli.WryPackageModule(findPackageJson(o.cwd));

    // Load wryFile
    const wryFile = wryModule.require(wryModule.pkg.wry.wryFile);
    if (typeof wryFile !== 'object')
      throw new WryError(`wryfile \`${wryFilePath}\` does not export an object`);

    const names = Object.entries(wryFile).filter(([key, val]) => !key.startsWith('_') && typeof val === 'function').map(([key,val]) => key);

    if (o.list) {
      names.forEach((name) => console.log(name));
      return;
    }

    // Ensure all requested tasks are available
    const invalidTasks = R.difference(o.tasks, names);
    if (invalidTasks.length !== 0)
      throw new WryError(`The requested task(s) (${invalidTasks.join()}) are not exported from \`${wryModule.pkg.wry.wryFile}\``);

    // Load extensions as defined by package.json
    cli.applyExtensions(Wry, wryModule);

    // Load extensions as defined by wryFile
    cli.applyExtensions(
      Wry,
      wryModule,
      o.tasks.map(task => ({
        name: '$' + task,
        func: wryFile[task]
      }))
    );

    // Create the wry object
    const wry = new Wry();

    const pipeline = wry[o.mode](o.tasks.map(task => wry['$' + task](o._cmdArgs, wryFile)));

    // resolve the tasks using the chosen mode (serial/parallel)
    if (o.graph) {
      console.log(util.inspect(pipeline.graphs, false, null));
    }
    else {
      await pipeline.resolve([]);
    }
  }
  catch (ex) {
    console.error(ex.message);
    if (!!ex.data)
      console.error(ex.data);
    process.exit(-1);
  }
};